/**
 * @description Test data and stubs for the Integration Hub tests.
 */
@IsTest
public class IntegrationHubTestData {

    private static final String RECORD_MARKER = 'IH_Test_Record';
    private static final String USER_DOMAIN = '@ihtest.example.com';

    /** @description Outbound event key (test records, selected fields, response handler). */
    public static final String OUT_KEY = 'ACC_OUT';
    /** @description Outbound event key that expects a callback. */
    public static final String CALLBACK_KEY = 'ACC_CB';
    /** @description Inbound event key. */
    public static final String IN_KEY = 'ACC_IN';
    /** @description Apex Class event key (StubPayloadBuilder: a Map and a String). */
    public static final String CLASS_KEY = 'ACC_CLASS';
    /** @description Apex Class event key whose builder returns a payload longer than the stored field. */
    public static final String LONG_KEY = 'ACC_LONG';
    /** @description Outbound event key with Business Data In Response (StubBusiness handler). */
    public static final String BUSINESS_KEY = 'ACC_BIZ';
    /** @description AuthMock mode: 401 to the first token, only the refreshed one is accepted. */
    public static final String REJECT_OLD = 'rejectOld';
    /** @description AuthMock mode: any token is accepted. */
    public static final String ACCEPT_ANY = 'acceptAny';

    /**
     * @description Creates the admin and reader users, the configuration and two test records.
     */
    public static void setupAll() {
        User admin = newUser('IH Admin');
        User reader = newUser('IH Reader');
        System.runAs(new User(Id = UserInfo.getUserId())) {
            IntegrationHubData.insertAll(new List<User>{ admin, reader });
            IntegrationHubData.insertAll(new List<PermissionSetAssignment>{
                assignment(admin.Id, 'Integration_Hub_Admin'), assignment(reader.Id, 'Integration_Hub_Read') });
        }
        System.runAs(admin) {
            IH_Connection__c conn = new IH_Connection__c(Name = 'Test system', Named_Credential__c = 'IH_Test', Active__c = true,
                Inbound_User__c = admin.Id, Timeout_Seconds__c = 10);
            IntegrationHubData.insertAll(new List<IH_Connection__c>{ conn });
            IntegrationHubData.insertAll(new List<IH_Event__c>{
                outboundEvent(OUT_KEY, conn.Id),
                callbackEvent(conn.Id),
                new IH_Event__c(Name = IN_KEY, Event_Key__c = IN_KEY, Direction__c = 'Inbound', Active__c = true,
                    Connection__c = conn.Id, Handler_Class__c = 'IntegrationHubTestData.StubInbound')
            });
            IntegrationHubData.insertAll(new List<IH_Connection__c>{
                new IH_Connection__c(Name = 'Record One', Named_Credential__c = RECORD_MARKER),
                new IH_Connection__c(Name = 'Record Two', Named_Credential__c = RECORD_MARKER)
            });
        }
    }

    /**
     * @description The admin user (Integration Hub Admin, inbound user of the connection).
     * @return the user
     */
    public static User admin() {
        return userNamed('IH Admin');
    }

    /**
     * @description The reader user (Integration Hub Read).
     * @return the user
     */
    public static User reader() {
        return userNamed('IH Reader');
    }

    /**
     * @description The business records the tests publish. Integration Connection records stand in for a business object, so
     * the tests do not depend on Account rules, encrypted fields or required fields of the org.
     * @return the records
     */
    public static List<IH_Connection__c> accounts() {
        return [SELECT Id, Name FROM IH_Connection__c WHERE Named_Credential__c = :RECORD_MARKER WITH SYSTEM_MODE ORDER BY Name LIMIT 10];
    }

    /**
     * @description An event by key.
     * @param key the event key
     * @return the event
     */
    public static IH_Event__c eventByKey(String key) {
        return [SELECT Id, Event_Key__c, Connection__c FROM IH_Event__c WHERE Event_Key__c = :key WITH SYSTEM_MODE LIMIT 1];
    }

    /**
     * @description Transactions of an event.
     * @param key the event key
     * @return the transactions
     */
    public static List<IH_Transaction__c> transactions(String key) {
        return [SELECT Id, Status__c, Direction__c, Request_Payload__c, Response_Body__c, Http_Status_Code__c, External_Reference_Id__c,
                Error_Message__c, Correlation_Id__c, Retry_Count__c, Completed_At__c, Related_Record_Id__c,
                Callback_Body__c, Request_Key__c, Name, Request_Url__c, Business_Status__c, Business_Result__c, Business_Error__c,
                Business_Runs__c
            FROM IH_Transaction__c WHERE Event_Name__c = :key WITH SYSTEM_MODE ORDER BY CreatedDate LIMIT 100];
    }

    /**
     * @description Inserts one transaction of the outbound event for the first Account.
     * @param key the event key
     * @param status the status
     * @return the transaction
     */
    public static IH_Transaction__c newTransaction(String key, String status) {
        IH_Event__c ev = eventByKey(key);
        IH_Connection__c a = accounts()[0];
        IH_Transaction__c t = new IH_Transaction__c(Event__c = ev.Id, Event_Name__c = key, Direction__c = 'Outbound',
            Status__c = status, Related_Record_Id__c = a.Id, Related_Object__c = 'IH_Connection__c', Retry_Count__c = 0,
            Request_Payload__c = '{"stored":true}', Error_Summary__c = 'HTTP 500');
        IntegrationHubData.insertAll(new List<IH_Transaction__c>{ t });
        return t;
    }

    /**
     * @description Record Ids of a list.
     * @param records the records
     * @return their Ids
     */
    public static List<Id> idsOf(List<SObject> records) {
        return new List<Id>(new Map<Id, SObject>(records).keySet());
    }

    /**
     * @description Inserts an outbound event whose payload is built by StubPayloadBuilder, on the test connection.
     * @param key the event key (LONG_KEY makes the builder return a payload longer than the stored field)
     * @return the event
     */
    public static IH_Event__c newApexClassEvent(String key) {
        IH_Event__c ev = outboundEvent(key, eventByKey(OUT_KEY).Connection__c);
        ev.Payload_Source__c = 'Apex Class';
        ev.Payload_Class__c = 'IntegrationHubTestData.StubPayloadBuilder';
        ev.Payload_Fields__c = null;
        ev.Response_Handler_Class__c = null;
        IntegrationHubData.insertAll(new List<IH_Event__c>{ ev });
        return ev;
    }

    /**
     * @description Inserts an outbound event with Business Data In Response whose handler is StubBusiness, on the test
     * connection (no callback).
     * @return the event
     */
    public static IH_Event__c newBusinessEvent() {
        IH_Event__c ev = outboundEvent(BUSINESS_KEY, eventByKey(OUT_KEY).Connection__c);
        ev.Business_Data_In_Response__c = true;
        ev.Response_Handler_Class__c = 'IntegrationHubTestData.StubBusiness';
        IntegrationHubData.insertAll(new List<IH_Event__c>{ ev });
        return ev;
    }

    /**
     * @description Makes the test connection Apex Auth with this Auth Class.
     * @param className the Auth Class (e.g. IntegrationHubTestData.StubAuth)
     * @return the connection
     */
    public static IH_Connection__c useApexAuth(String className) {
        IH_Connection__c conn = new IH_Connection__c(Id = eventByKey(OUT_KEY).Connection__c, Connection_Type__c = 'Apex Auth',
            Auth_Class__c = className);
        IntegrationHubData.updateAll(new List<IH_Connection__c>{ conn });
        return conn;
    }

    /**
     * @description Switches auto-retry on for an event.
     * @param key the event key
     * @param maxRetries Auto Retry Max
     * @param minutes Retry After (minutes)
     */
    public static void setAutoRetry(String key, Integer maxRetries, Integer minutes) {
        IntegrationHubData.updateAll(new List<IH_Event__c>{
            new IH_Event__c(Id = eventByKey(key).Id, Auto_Retry_Max__c = maxRetries, Retry_After_Minutes__c = minutes) });
    }

    /**
     * @description A transaction with its auto-retry fields, Next Retry At and error.
     * @param txnId the transaction
     * @return the transaction
     */
    public static IH_Transaction__c retryState(Id txnId) {
        return [SELECT Id, Status__c, Next_Retry_At__c, Auto_Retries__c, Auto_Retry_Max__c, Error_Message__c, Error_Summary__c,
                Http_Status_Code__c, External_Reference_Id__c
            FROM IH_Transaction__c WHERE Id = :txnId WITH SYSTEM_MODE LIMIT 1];
    }

    private static IH_Event__c callbackEvent(Id connId) {
        IH_Event__c ev = outboundEvent(CALLBACK_KEY, connId);
        ev.Expects_Callback__c = true;
        return ev;
    }

    private static IH_Event__c outboundEvent(String key, Id connId) {
        return new IH_Event__c(Name = key, Event_Key__c = key, Direction__c = 'Outbound', Active__c = true, Connection__c = connId,
            Related_Object__c = 'IH_Connection__c', Path__c = '/records/{recordId}', Http_Method__c = 'POST',
            Payload_Fields__c = 'Name, CreatedDate\nOwner.Name', Retention_Days__c = 90, Callback_Timeout_Hours__c = 24,
            Share_With_Related_Record__c = true, Response_Handler_Class__c = 'IntegrationHubTestData.StubResponse');
    }

    private static User newUser(String lastName) {
        List<Profile> profiles = [SELECT Id FROM Profile WHERE Name = 'Standard User' WITH SYSTEM_MODE LIMIT 1];
        Id profileId = profiles.isEmpty() ? UserInfo.getProfileId() : profiles[0].Id;
        String unique = EncodingUtil.convertToHex(Crypto.generateAesKey(128)).left(10);
        return new User(LastName = lastName, Alias = unique.left(8), Email = unique + '@example.com',
            Username = unique + '.' + tagOf(lastName) + USER_DOMAIN, ProfileId = profileId, EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US', LocaleSidKey = 'en_US', TimeZoneSidKey = 'America/Chicago');
    }

    private static PermissionSetAssignment assignment(Id userId, String setName) {
        PermissionSet ps = [SELECT Id FROM PermissionSet WHERE Name = :setName WITH SYSTEM_MODE LIMIT 1];
        return new PermissionSetAssignment(AssigneeId = userId, PermissionSetId = ps.Id);
    }

    private static User userNamed(String lastName) {
        String pattern = '%.' + tagOf(lastName) + USER_DOMAIN;
        return [SELECT Id FROM User WHERE Username LIKE :pattern WITH SYSTEM_MODE LIMIT 1];
    }

    private static String tagOf(String lastName) {
        return lastName.deleteWhitespace().toLowerCase();
    }

    /**
     * @description HTTP mock: a fixed status and body, or a callout error.
     */
    public class Mock implements HttpCalloutMock {
        private final Integer code;
        private final String body;

        /**
         * @description A mock reply; code 0 throws a callout error.
         * @param statusCode the HTTP status
         * @param replyBody the body
         */
        public Mock(Integer statusCode, String replyBody) {
            code = statusCode;
            body = replyBody;
        }

        /**
         * @description Answers the request.
         * @param req the request
         * @return the reply
         */
        public HttpResponse respond(HttpRequest req) {
            if (code == 0) {
                throw new CalloutException('Connection refused');
            }
            HttpResponse res = new HttpResponse();
            res.setStatusCode(code);
            res.setBody(body);
            return res;
        }
    }

    /**
     * @description HTTP mock for Apex Auth: no Authorization header answers 400; in mode REJECT_OLD the first token
     * ("Bearer OLD") answers 401 and only the refreshed one ("Bearer NEW") is accepted. A 200 answer carries the
     * header it got as the reference.
     */
    public class AuthMock implements HttpCalloutMock {
        private final Boolean rejectOld;

        /**
         * @description A mock.
         * @param mode REJECT_OLD to answer 401 to "Bearer OLD"; anything else accepts any token
         */
        public AuthMock(String mode) {
            rejectOld = mode == REJECT_OLD;
        }

        /**
         * @description Answers the request.
         * @param req the request
         * @return the reply
         */
        public HttpResponse respond(HttpRequest req) {
            String auth = req.getHeader('Authorization');
            HttpResponse res = new HttpResponse();
            if (String.isBlank(auth)) {
                res.setStatusCode(400);
                res.setBody('{"error":"no login"}');
            } else if (rejectOld && auth != 'Bearer NEW') {
                res.setStatusCode(401);
                res.setBody('{"error":"expired"}');
            } else {
                res.setStatusCode(200);
                res.setBody(JSON.serialize(new Map<String, Object>{ 'reference' => auth }));
            }
            return res;
        }
    }

    /**
     * @description Connection auth class: "Bearer OLD", or "Bearer NEW" on a refresh.
     */
    public class StubAuth implements IntegrationHub.IConnectionAuth {
        /**
         * @description Sets the header.
         * @param ctx the request
         */
        @SuppressWarnings('PMD.ApexSuggestUsingNamedCred')
        public void authorize(IntegrationHub.AuthContext ctx) {
            ctx.request.setHeader('Authorization', ctx.refresh == true ? 'Bearer NEW' : 'Bearer OLD');
        }
    }

    /**
     * @description Connection auth class whose login is always refused.
     */
    public class StubAuthBroken implements IntegrationHub.IConnectionAuth {
        /**
         * @description Throws.
         * @param ctx the request
         */
        public void authorize(IntegrationHub.AuthContext ctx) {
            throw new IntegrationHub.HubException('login refused');
        }
    }

    /**
     * @description Connection auth class whose token URL cannot be reached (a callout error).
     */
    public class StubAuthOffline implements IntegrationHub.IConnectionAuth {
        /**
         * @description Throws a callout error.
         * @param ctx the request
         */
        public void authorize(IntegrationHub.AuthContext ctx) {
            throw new CalloutException('Read timed out');
        }
    }

    /**
     * @description Inbound handler: creates a record; mode fail, boom or none for the other outcomes.
     */
    public class StubInbound implements IntegrationHub.IInboundHandler {
        /**
         * @description Handles the call.
         * @param ctx the call
         * @return the result
         */
        public IntegrationHub.InboundResult handle(IntegrationHub.InboundContext ctx) {
            String mode = String.valueOf(ctx.data.get('mode'));
            if (mode == 'fail') {
                return IntegrationHub.inboundFailure(400, 'Name is missing');
            }
            if (mode == 'boom') {
                throw new IntegrationHub.HubException('Handler crashed');
            }
            if (mode == 'none') {
                return null;
            }
            IH_Connection__c a = new IH_Connection__c(Name = String.valueOf(ctx.data.get('name')));
            IntegrationHubData.insertAll(new List<IH_Connection__c>{ a });
            return IntegrationHub.inboundSuccess(a.Id, new Map<String, Object>{ 'name' => a.Name });
        }
    }

    /**
     * @description Response handler: marks the transaction; throws when the body contains boom.
     */
    public class StubResponse implements IntegrationHub.IResponseHandler {
        /**
         * @description Handles the reply.
         * @param ctx the reply
         */
        public void handle(IntegrationHub.ResponseContext ctx) {
            if (ctx.body != null && ctx.body.contains('boom')) {
                throw new IntegrationHub.HubException('Handler failed');
            }
            ctx.txn.Correlation_Id__c = ctx.isCallback ? 'CALLBACK' : 'HANDLED';
        }
    }

    /**
     * @description Business data handler: needs ctx.data, throws when it holds "fail", marks the transaction and sets
     * the result line.
     */
    public class StubBusiness implements IntegrationHub.IResponseHandler {
        /**
         * @description Handles the business data.
         * @param ctx the reply or callback
         */
        public void handle(IntegrationHub.ResponseContext ctx) {
            if (ctx.data == null || ctx.data.containsKey('fail')) {
                throw new IntegrationHub.HubException('Business data rejected');
            }
            ctx.txn.Correlation_Id__c = 'BUSINESS';
            ctx.result = 'Voucher ' + ctx.data.get('voucher') + (ctx.isCallback ? ' (callback)' : '');
        }
    }

    /**
     * @description Payload class: a Map for the first record and a String for the second (nothing for the rest);
     * a 140000-character String for every record when the event key is LONG_KEY; throws when the event key is BOOM.
     */
    public class StubPayloadBuilder implements IntegrationHub.IPayloadBuilder {
        /**
         * @description Builds the bodies.
         * @param request the batch
         * @return the body per record Id
         */
        public Map<Id, Object> build(IntegrationHub.PayloadRequest request) {
            if (request.eventKey == 'BOOM') {
                throw new IntegrationHub.HubException('Builder crashed');
            }
            Map<Id, Object> bodies = new Map<Id, Object>();
            for (Integer i = 0; i < request.recordIds.size(); i++) {
                bodies.put(request.recordIds[i], bodyAt(request.eventKey, i, request.recordIds.size()));
            }
            return bodies;
        }

        private Object bodyAt(String eventKey, Integer index, Integer batchSize) {
            if (eventKey == LONG_KEY) {
                return '{"pad":"' + 'x'.repeat(140000) + '"}';
            }
            if (index == 0) {
                return new Map<String, Object>{ 'kind' => 'map', 'batch' => batchSize };
            }
            return index == 1 ? '{"kind":"string"}' : null;
        }
    }

    /**
     * @description Finalizer context with a chosen result.
     */
    public class StubFinalizerContext implements FinalizerContext {
        private final ParentJobResult result;

        /**
         * @description A context with this result.
         * @param jobResult the result
         */
        public StubFinalizerContext(ParentJobResult jobResult) {
            result = jobResult;
        }

        /**
         * @description Job Id.
         * @return null
         */
        public Id getAsyncApexJobId() {
            return null;
        }

        /**
         * @description Request Id.
         * @return a fixed value
         */
        public String getRequestId() {
            return 'test';
        }

        /**
         * @description Job result.
         * @return the result
         */
        public ParentJobResult getResult() {
            return result;
        }

        /**
         * @description Job exception.
         * @return an exception when the job failed
         */
        public Exception getException() {
            return result == ParentJobResult.SUCCESS ? null : new IntegrationHub.HubException('Job died');
        }
    }
}
